import os
import extern
import shutil
import pytest
from utils import assert_equal_tsv
path_to_data = os.path.join(os.path.dirname(os.path.realpath(__file__)), 'data')

@pytest.fixture
def end_to_end():
    """Remove truth and reads generated by community.yaml"""
    files_to_remove = [
        f"{path_to_data}/tmp/small_1.fq.gz",
        f"{path_to_data}/tmp/small_2.fq.gz",
        f"{path_to_data}/tmp/truth.tsv"
    ]
    def cleanup():
        for file in files_to_remove:
            try:
                os.remove(file)
            except FileNotFoundError:
                pass
    
    cleanup()
    yield
    cleanup()

